const rows = $input.all().map((i) => i.json || {}).filter((r) => Object.keys(r).length > 0);
const toText = (v) => (v === null || v === undefined) ? '' : (typeof v === 'object' ? JSON.stringify(v) : String(v));
if (rows.length === 0) return [{ json: { row_count: 0, column_count: 0, columns: [], records: [] } }];
const columns = [];
for (const r of rows) for (const k of Object.keys(r)) if (!columns.includes(k)) columns.push(k);
const seen = new Set(); const records = []; const teams = new Set(); const mgrs = new Set();
for (const r of rows) {
  const id = toText(r['Employee ID']);
  if (id !== '' && seen.has(id)) continue;
  seen.add(id);
  records.push(columns.map((c) => toText(r[c])));
  if (toText(r['Team'])) teams.add(toText(r['Team']));
  if (toText(r["Manager's Name"])) mgrs.add(toText(r["Manager's Name"]));
}
return [{ json: {
  row_count: records.length, column_count: columns.length, columns, records,
  teams_present: [...teams].sort(), manager_count: mgrs.size,
  snapshot_date: toText(rows[0]['Snapshot Date']),
} }];

// Name the stage that lost the rows.
const rows = $input.all().map((i) => i.json || {}).filter((r) => Object.keys(r).length > 0);
const L = [];
L.push('EVERYONE-LEVEL FRONTLINE ROSTER ABORTED - zero rows.');
L.push('The Google Sheet was NOT cleared. Its previous contents are intact.');
L.push('');
if (rows.length === 0) {
  L.push('DIAGNOSIS: the profiling query itself returned nothing, so');
  L.push('vw_dim_employee_detail is unreachable or empty in the last 60 days.');
} else {
  const r = rows[0];
  for (const [k, v] of Object.entries(r)) L.push(`  ${k} = ${v}`);
  L.push('');
  if (Number(r.view_rows || 0) === 0) {
    L.push('DIAGNOSIS: no rows on the latest DateValue. Check the view is still loading.');
  } else if (Number(r.workgroups_in_scope || 0) === 0) {
    L.push('DIAGNOSIS: workgroup 12056 matched NO workgroups in the lookup table, so');
    L.push('the scope resolved to an empty set. This is the documented depth limit -');
    L.push('the lookup only exposes three hierarchy levels.');
    L.push('FIX: in the final SELECT, replace  WHERE w.in_scope = 1  with');
    L.push("  WHERE p.Team = 'Frontline'   (the view carries its own Team column)");
  } else if (Number(r.employees_in_scope || 0) === 0) {
    L.push(`DIAGNOSIS: ${r.workgroups_in_scope} workgroups are in scope, but NO employee in`);
    L.push('the view sits in any of them. The two sources disagree on WgID, so the');
    L.push('workgroup join is the wrong bridge.');
    L.push("FIX: replace  WHERE w.in_scope = 1  with  WHERE p.Team = 'Frontline'");
  } else {
    L.push(`DIAGNOSIS: ${r.employees_in_scope} employees ARE in scope, so the filters are fine`);
    L.push('and something later dropped them. Send this output back.');
  }
}
return [{ json: { diagnosis: L.join('\n') } }];

const TAB_NAME = 'Sheet1';
const CHUNK_ROWS = 5000;
const source = $('Code - Normalize Roster').first().json;
const allRows = [source.columns || [], ...(source.records || [])];
const chunks = [];
for (let offset = 0; offset < allRows.length; offset += CHUNK_ROWS) {
  const slice = allRows.slice(offset, offset + CHUNK_ROWS);
  const startRow = offset + 1;
  chunks.push({ chunk_index: chunks.length + 1, chunk_rows: slice.length, start_row: startRow,
    request_body: { valueInputOption: 'RAW',
      data: [{ range: `${TAB_NAME}!A${startRow}`, majorDimension: 'ROWS', values: slice }] } });
}
return chunks.map((c) => ({ json: { ...c, chunk_total: chunks.length } }));
